<script setup lang="ts">import { Head, Link } from '@inertiajs/vue3'; import { Plus } from '@lucide/vue'; import { Button } from '@/components/ui/button'; type Order={id:string;document_number:string;planned_for:string;recipe:string;version:number;responsible:string;status_label:string;flour_quantity:string;total_cost:number}; defineProps<{orders:{data:Order[]};canManage:boolean}>(); const money=(value:number)=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(value);</script><template><Head title="Producción" /><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header class="flex justify-between gap-3"><div><h1 class="text-2xl font-semibold">Producción</h1><p class="text-sm text-muted-foreground">De harina e ingredientes a productos terminados.</p></div><Button v-if="canManage" as-child><Link href="/production/create"><Plus /> Planear producción</Link></Button></header><section class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3">Orden</th><th class="px-4 py-3">Receta</th><th class="px-4 py-3">Harina</th><th class="px-4 py-3">Responsable</th><th class="px-4 py-3">Estado</th><th class="px-4 py-3">Costo</th><th></th></tr></thead><tbody class="divide-y"><tr v-for="order in orders.data" :key="order.id"><td class="px-4 py-3"><p class="font-medium">{{ order.document_number }}</p><p class="text-xs text-muted-foreground">{{ order.planned_for }}</p></td><td class="px-4 py-3">{{ order.recipe }} · v{{ order.version }}</td><td class="px-4 py-3">{{ order.flour_quantity }} kg</td><td class="px-4 py-3">{{ order.responsible }}</td><td class="px-4 py-3">{{ order.status_label }}</td><td class="px-4 py-3">{{ money(order.total_cost) }}</td><td class="px-4 py-3 text-right"><Link :href="`/production/${order.id}`" class="font-medium text-amber-700 hover:underline">Ver</Link></td></tr></tbody></table><p v-if="orders.data.length===0" class="p-10 text-center text-sm text-muted-foreground">No hay producciones registradas.</p></section></main></template>
